from pathlib import Path
import json,shutil,hashlib,os,importlib.util
from PIL import Image
D=Path(__file__).resolve().parent;R=D.parents[2]
P=R/'art/creatures/rabbito-family-v1/conde-da-ultima-hora/concept-v1'
P.mkdir(parents=True,exist_ok=True)
data=json.loads((D/'producao.json').read_text(encoding='utf-8'))
def write(p,t):p.write_text(t,encoding='utf-8')
def dump(p,v):write(p,json.dumps(v,ensure_ascii=False,indent=2)+'\n')
def rel(p,b):return os.path.relpath(p,b).replace('\\','/')
shutil.copy2(data['source'],P/'concept.png');write(P/'prompt.txt',data['prompt']+'\n')
review='Dois braços e duas pernas em posição de duelo, uma perna à frente e outra estendida. Duas orelhas-pipa muito longas, máscara com aberturas e olhos vermelhos visíveis; rosto leporino lilás exposto. Armadura preta em placas no peito, braços e canelas; lapelas e abas lembram casaca formal, gola alta e capa preta/roxa. Relógio redondo com coroa, mostrador claro e dois ponteiros forma a guarda da espada; mão segura a empunhadura atrás da guarda, lâmina contínua e ponta completa. Rabiola preta/prateada com três laços roxos; trecho da raiz está parcialmente oculto pelo punho/quadril. Uma orelha e os pés se aproximam da borda, mas não há corte visível. Pequenos filetes prateados percorrem várias placas, acrescentando detalhe em relação às superfícies mais quietas da forma de velocidade.\n\nConcept 2D com fundo branco. As partes ocultas, articulação da capa e empunhadura em outras vistas precisam de uma prancha técnica futura; esta imagem não certifica rig, sprites ou animações.'
write(P/'brief.md','# Conde da Última Hora — proposta\n\n## Definido pelo autor\n\nEvolução das sombras do Rabbito, adulta, esbelta, preta e roxa, olhos vermelhos; armadura vampiresca vintage e formal, ainda reconhecível como armadura. Arma: relógio-espada antigo, direção draculiana.\n\n## Proposta visual\n\nNome provisório: Conde da Última Hora. Armadura de colete/casaca em placas rígidas, gola alta e capa de papel tensionado. Rosto leporino com máscara aberta nos olhos; duas orelhas-pipa e uma rabiola longa com três laços preservam parentesco. Relógio antigo é a guarda; a lâmina segue a ideia de um ponteiro. Verbo: marcar a distância e responder no instante da abertura. Lore proposta: troca a pressa por uma espera calculada, mas precisa agir antes de deixar passar a chance de proteger alguém.\n\n## Observado\n\n'+review+'\n\n## Cânone e incógnitas\n\nA sombra é a direção da evolução solicitada, sem inferir possessão pelo Carretel Negro, vilania, nova alma ou transformação da forma aprovada de velocidade. Nome, rota exata, predecessor jovem, obtenção, poderes e implementação não definidos. Não substitui adultos, rigs ou chart existentes.\n')
write(P/'revisao.md','# Conferência\n\n'+review+'\n\nEstado de design: proposto. Adulto pedido pelo autor; nome e posição no chart permanecem propostas.\n')
with Image.open(P/'concept.png') as im:
    meta=dict(width=im.width,height=im.height,mode=im.mode,alpha_extrema=im.getextrema()[-1] if im.mode=='RGBA' else None)
dump(P/'manifest.json',dict(id='rabbito-conde-da-ultima-hora',family_id='rabbito',stage=4,name='Conde da Última Hora (proposta)',date=data['date'],decision_status='proposed',production_status='concept',implementation_status='not_integrated',tool='image_gen.imagegen',source=data['source'],sha256=hashlib.sha256((P/'concept.png').read_bytes()).hexdigest(),prompt='prompt.txt',reference=rel(R/'art/creatures/rabbito-family-v1/velocista-relampago/concept-v1/concept.png',P),reference_role='Forma própria aceita pelo autor: parentesco; anatomia, equipamento e gesto redesenhados. Nenhuma imagem externa anexada.',**meta))
chart=dict(family_id='rabbito',scope='Alternativa adulta das sombras; posição exata na linha e predecessor não definidos. Sem integração, possessão ou substituição de designs aprovados.',nodes=[dict(id='rabbito-conde-da-ultima-hora',name='Conde da Última Hora (proposta)',kind='stage',stage=4,identity='Adulto esbelto com armadura de casaca vampiresca preta/roxa, olhos vermelhos, orelhas-pipa e relógio-espada.',story='Espera calculada exige escolher o instante de agir; interpretação proposta.',decision_status='proposed',production_status='concept',art=rel(P/'concept.png',D),brief=rel(P/'brief.md',D))],edges=[])
dump(D/'chart.json',chart)
spec=importlib.util.spec_from_file_location('v',R/'.agents/skills/soulmonsters-charts/scripts/validar_chart.py');v=importlib.util.module_from_spec(spec);spec.loader.exec_module(v)
errors=v.validate(chart,D);assert not errors,errors;dump(D/'validacao.json',dict(chart_errors=errors,concept_exists=True,visual_scope='Imagem aberta e conferida; sem animação, integração ou aprovação automática.'))
write(D/'CHART.md','# Conde da Última Hora\n\nAdulto das sombras proposto para a família Rabbito. Predecessor e caminho não definidos; não é automaticamente possessão.\n\n[Concept]('+rel(P/'concept.png',D)+') · [Brief]('+rel(P/'brief.md',D)+') · [Conferência]('+rel(P/'revisao.md',D)+').\n')
write(D/'index.html','<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rabbito · Conde da Última Hora</title><style>body{margin:0;background:#191520;color:#eee9df;font:18px/1.6 system-ui}main{max-width:1100px;margin:auto;padding:32px 24px}img{width:100%;height:auto}a{color:#c6a9eb}a:focus-visible{outline:3px solid white;outline-offset:5px}</style><main><h1>Conde da Última Hora</h1><p>Nome provisório para uma evolução adulta das sombras do Rabbito: armadura formal vampiresca, olhos vermelhos e relógio-espada.</p><a href="'+rel(P/'concept.png',D)+'"><img src="'+rel(P/'concept.png',D)+'" alt="Soulmonster leporino esbelto de armadura preta e roxa, orelhas-pipa longas e olhos vermelhos, segurando uma espada com relógio na guarda"></a><p><a href="'+rel(P/'brief.md',D)+'">Brief</a> · <a href="'+rel(P/'revisao.md',D)+'">Conferência</a></p><p>Posição na linha e nome propostos. Sem vínculo automático com possessão ou Carretel Negro.</p></main></html>')
print('Concept salvo, manifesto e conferência registrados, chart documental validado.')
